tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
const stem = 'visits/5f242af3-80ed-4e14-ab00-f46891bac98a';
const log = JSON.parse(readFileSync(stem + '.json', 'utf8'));
assert.equal(log.error, null);
assert.deepEqual(log.actions, log.requested);
const [open, , , rejected, corrected, saved, , reload] = log.timeline;
const value = step => step.state.fields.find(field => field.id === 'address').value;
assert.equal(open.state.heading, 'River desk');
assert.equal(value(open), 'desk@example.test');
assert.deepEqual(rejected.state.status, ['Enter a complete address.', 'Saved contact: desk@example.test']);
assert.equal(value(corrected), 'river@example.test');
assert.deepEqual(saved.state.status, ['Saved: river@example.test']);
assert.equal(reload.action.op, 'reload');
assert.equal(reload.state.heading, 'River desk');
assert.equal(value(reload), 'river@example.test');
assert.deepEqual(reload.state.status, ['Saved contact: river@example.test']);
assert.equal(createHash('sha256').update(readFileSync(stem + '.png')).digest('hex'), log.screenSha256);
console.log('Acceptance evidence verified');
NODE
ls -d ./form-browser-* ./com.google.Chrome.*"
